#include <zephyr/kernel.h>
#include <zephyr/sys/notify.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

/* Callback test */
static K_SEM_DEFINE(callback_sem, 0, 1);
static int callback_result;

static void my_callback(struct sys_notify *obj, void *user_data, int result)
{
    ARG_UNUSED(obj);
    ARG_UNUSED(user_data);
    callback_result = result;
    k_sem_give(&callback_sem);
}

ZTEST_USER(sys_notify_api, test_callback)
{
    struct sys_notify cb_notify;
    int rc;

    callback_result = 0;

    sys_notify_callback_init(&cb_notify, my_callback, NULL);

    rc = sys_notify_callback_submit(&cb_notify, k_current_get(), 123);
    zassert_equal(rc, 0, "sys_notify_callback_submit failed with %d", rc);

    k_sem_take(&callback_sem, K_FOREVER);
    zassert_equal(callback_result, 123, "Callback result mismatch");
}

/* Signal test */
static K_SEM_DEFINE(signal_sem_ready, 0, 1);
static K_SEM_DEFINE(signal_sem_done, 0, 1);

static void signal_thread_entry(void *p1, void *p2, void *p3)
{
    struct sys_notify *notify_obj = (struct sys_notify *)p1;
    int *result_ptr = (int *)p2;
    int rc;

    k_sem_give(&signal_sem_ready); /* Signal that thread is ready */

    /* Wait for the main thread to submit the signal */
    k_sem_take(&signal_sem_done, K_FOREVER);

    rc = sys_notify_signal_fetch(notify_obj, result_ptr, K_FOREVER);
    zassert_equal(rc, 0, "sys_notify_signal_fetch failed with %d", rc);

    k_sem_give(&signal_sem_done); /* Signal that fetch is complete */
}

K_THREAD_STACK_DEFINE(signal_thread_stack, STACK_SIZE);
static struct k_thread signal_thread_data;

static void sys_notify_api_test_signal(void)
{
    int rc;
    k_tid_t tid;
    struct sys_notify signal_notify; /* Make it local to the test function */
    int signal_result_val; /* Local variable to store the result */

    k_sem_reset(&signal_sem_ready);
    k_sem_reset(&signal_sem_done);

    tid = k_thread_create(&signal_thread_data, signal_thread_stack,
                          K_THREAD_STACK_SIZEOF(signal_thread_stack),
                          signal_thread_entry, &signal_notify, &signal_result_val, NULL,
                          K_PRIO_PREEMPT(0), 0, K_NO_WAIT);
    zassert_not_equal(tid, NULL, "Failed to create thread");

    k_sem_take(&signal_sem_ready, K_FOREVER); /* Wait for helper thread to be ready */

    sys_notify_signal_init(&signal_notify);

    rc = sys_notify_signal_submit(&signal_notify, tid, 456);
    zassert_equal(rc, 0, "sys_notify_signal_submit failed with %d", rc);

    k_sem_give(&signal_sem_done); /* Tell helper thread to fetch */

    k_sem_take(&signal_sem_done, K_FOREVER); /* Wait for helper thread to complete fetch */

    zassert_equal(signal_result_val, 456, "Fetched signal result mismatch");

    k_thread_abort(tid);
}

ZTEST_SUITE(sys_notify_api, NULL, NULL, NULL, NULL, NULL);

ZTEST_USER(sys_notify_api, test_signal)
{
    sys_notify_api_test_signal();
}
